-- 探險家與千面旅人改算 Harbor 驗證過的角色數（owner 2026-11-22）：遊玩頁回報的「開過對話」沒有驗證，
-- 上線後有成員幾小時內開了數百個角色。現在一個角色要自己聊滿 10 輪才算，每天最多計入 10 個新角色。
-- 「初次見面」仍看開過的對話。已經發出的探險家徽章照舊保留（每小時掃描只發不收）。
ALTER TABLE badge_qualifications ADD COLUMN explored_roles INTEGER NOT NULL DEFAULT 0 CHECK(explored_roles>=0);
ALTER TABLE badge_qualifications ADD COLUMN explored_roles_500_at INTEGER;
-- 千面旅人的越線查詢每次徽章統計都會跑：只讀已滿 500 的成員，不掃整張表。
CREATE INDEX badge_qualifications_explored_500 ON badge_qualifications(explored_roles_500_at) WHERE explored_roles_500_at IS NOT NULL;
UPDATE community_badge_definitions SET descriptions='{"zh-Hant": "和 10 個不同角色各聊滿 10 輪（每天最多計入 10 個新角色）。", "zh-Hans": "和 10 个不同角色各聊满 10 轮（每天最多计入 10 个新角色）。", "en": "Chat at least 10 rounds each with 10 different characters. Up to 10 new characters count per day.", "ja": "10 人のキャラクターとそれぞれ 10 往復以上会話する（1 日に数えるのは新しいキャラクター 10 人まで）。", "ko": "서로 다른 캐릭터 10명과 각각 10번 이상 대화를 주고받으면 획득해요. 하루에 새 캐릭터는 10명까지 세요."}',metric='explored_roles' WHERE key='player_explorer_10';
UPDATE community_badge_definitions SET descriptions='{"zh-Hant": "和 50 個不同角色各聊滿 10 輪（每天最多計入 10 個新角色）。", "zh-Hans": "和 50 个不同角色各聊满 10 轮（每天最多计入 10 个新角色）。", "en": "Chat at least 10 rounds each with 50 different characters. Up to 10 new characters count per day.", "ja": "50 人のキャラクターとそれぞれ 10 往復以上会話する（1 日に数えるのは新しいキャラクター 10 人まで）。", "ko": "서로 다른 캐릭터 50명과 각각 10번 이상 대화를 주고받으면 획득해요. 하루에 새 캐릭터는 10명까지 세요."}',metric='explored_roles' WHERE key='player_explorer_50';
