UPDATE community_badge_definitions SET descriptions='{"zh-Hant": "全站第一位和 500 個不同角色各聊滿 10 輪的成員（每天最多計入 10 個新角色）。全站只有一位。", "zh-Hans": "全站第一位和 500 个不同角色各聊满 10 轮的成员（每天最多计入 10 个新角色）。全站只有一位。", "en": "The first member to chat at least 10 rounds each with 500 different characters. Up to 10 new characters count per day. Only one member holds it.", "ja": "全サイトで最初に 500 人のキャラクターとそれぞれ 10 往復以上会話したメンバー（1 日に数えるのは新しいキャラクター 10 人まで）。全サイトで 1 人だけ。", "ko": "사이트에서 처음으로 서로 다른 캐릭터 500명과 각각 10번 이상 대화를 주고받은 멤버예요. 하루에 새 캐릭터는 10명까지 세요. 사이트 전체에서 한 명뿐이에요."}' WHERE key='sole_wanderer';
UPDATE community_badge_definitions SET descriptions='{"zh-Hant": "全站第 2–10 位達成「千面旅人」的成員（和 500 個角色各聊滿 10 輪）。", "zh-Hans": "全站第 2–10 位达成「千面旅人」的成员（和 500 个角色各聊满 10 轮）。", "en": "The 2nd to 10th members to reach Wanderer of a Thousand Tales (10 rounds each with 500 characters).", "ja": "「千の物語の旅人」を全サイトで 2〜10 人目に達成したメンバー（500 人のキャラとそれぞれ 10 往復）。", "ko": "''천 개의 이야기 여행자'' 조건(캐릭터 500명과 각각 10번 대화)을 사이트 2~10번째로 달성한 멤버예요."}' WHERE key='sole_wanderer_pioneer';
UPDATE public_catalog_clock SET revision=lower(hex(randomblob(16))) WHERE id=1;
